#include <string>
#include <string_view>
#include <vector>

int indexOf(const std::vector<std::string>& names, std::string_view target)
{
    for (std::size_t i{ 0 }; i < names.size(); ++i)
    {
        if (names[i] == target)
        {
            return static_cast<int>(i);
        }
    }
    return -1;
}

unitTests:
TEST("finds a name") { const std::vector<std::string> v{ "Ann", "Bo", "Cy" }; CHECK_EQ(indexOf(v, "Ann"), 0); CHECK_EQ(indexOf(v, "Cy"), 2); }
TEST("first match wins") { CHECK_EQ(indexOf({ "x", "y", "x" }, "x"), 0); CHECK_EQ(indexOf({ "x", "y", "y" }, "y"), 1); }
TEST("missing") { CHECK_EQ(indexOf({ "Ann", "Bo" }, "Zed"), -1); CHECK_EQ(indexOf({}, "Ann"), -1); }

